// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Login Log in with username and password; sets the session cookie.
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End the current session and clear the cookie.
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change the password. Signs out every other session; this one stays signed in.
	// (POST /auth/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// UndoEvent Undo an event. It is kept but ignored from now on.
	// (DELETE /events/{id})
	UndoEvent(w http.ResponseWriter, r *http.Request, id Id)
	// ExportData Download everything as a zip (format in docs/export-format.md).
	// (GET /export)
	ExportData(w http.ResponseWriter, r *http.Request)
	// IdentifyPlant Suggest species for a plant photo with Pl@ntNet (optional; needs GROWER_PLANTNET_API_KEY).
	// (POST /identify)
	IdentifyPlant(w http.ResponseWriter, r *http.Request)
	// ListLocations All locations, ordered by name, with how many active plants each holds.
	// (GET /locations)
	ListLocations(w http.ResponseWriter, r *http.Request)

	// (POST /locations)
	CreateLocation(w http.ResponseWriter, r *http.Request)
	// DeleteLocation Delete a location. Its plants keep existing with no location.
	// (DELETE /locations/{id})
	DeleteLocation(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateLocation Replace a location's fields.
	// (PUT /locations/{id})
	UpdateLocation(w http.ResponseWriter, r *http.Request, id Id)
	// GetMe The signed-in user, their settings and the server version.
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)

	// (DELETE /measurements/{id})
	DeleteMeasurement(w http.ResponseWriter, r *http.Request, id Id)

	// (PUT /measurements/{id})
	UpdateMeasurement(w http.ResponseWriter, r *http.Request, id Id)
	// DeletePhoto Delete a photo and its files. If it was the cover, the newest remaining photo becomes the cover.
	// (DELETE /photos/{id})
	DeletePhoto(w http.ResponseWriter, r *http.Request, id Id)
	// UpdatePhoto Replace a photo's caption and date.
	// (PUT /photos/{id})
	UpdatePhoto(w http.ResponseWriter, r *http.Request, id Id)
	// ListPlants Plants ordered by name. Archived plants are excluded unless archived=true.
	// (GET /plants)
	ListPlants(w http.ResponseWriter, r *http.Request, params ListPlantsParams)

	// (POST /plants)
	CreatePlant(w http.ResponseWriter, r *http.Request)
	// DeletePlant Permanently delete a plant. Archiving is the reversible option.
	// (DELETE /plants/{id})
	DeletePlant(w http.ResponseWriter, r *http.Request, id Id)

	// (GET /plants/{id})
	GetPlant(w http.ResponseWriter, r *http.Request, id Id)
	// UpdatePlant Replace a plant's fields, including whether it is archived.
	// (PUT /plants/{id})
	UpdatePlant(w http.ResponseWriter, r *http.Request, id Id)
	// ApplySpeciesCare Apply the linked species' care defaults to the plant's watering task.
	// (POST /plants/{id}/apply-species)
	ApplySpeciesCare(w http.ResponseWriter, r *http.Request, id Id)
	// SetPlantCover Choose the plant's cover photo, or clear it with null.
	// (PUT /plants/{id}/cover)
	SetPlantCover(w http.ResponseWriter, r *http.Request, id Id)
	// ListPlantEvents A plant's care history, newest first. Undone events are left out.
	// (GET /plants/{id}/events)
	ListPlantEvents(w http.ResponseWriter, r *http.Request, id Id, params ListPlantEventsParams)
	// ListMeasurements A plant's measurements, newest measured_on first.
	// (GET /plants/{id}/measurements)
	ListMeasurements(w http.ResponseWriter, r *http.Request, id Id)

	// (POST /plants/{id}/measurements)
	CreateMeasurement(w http.ResponseWriter, r *http.Request, id Id)
	// ListPlantPhotos A plant's photos, newest taken_at first.
	// (GET /plants/{id}/photos)
	ListPlantPhotos(w http.ResponseWriter, r *http.Request, id Id)
	// UploadPhoto Upload a JPEG or PNG (max 15 MB). The plant's first photo becomes its cover.
	// (POST /plants/{id}/photos)
	UploadPhoto(w http.ResponseWriter, r *http.Request, id Id)
	// ListPlantTasks A plant's care tasks, ordered by next due date.
	// (GET /plants/{id}/tasks)
	ListPlantTasks(w http.ResponseWriter, r *http.Request, id Id)

	// (POST /plants/{id}/tasks)
	CreateTask(w http.ResponseWriter, r *http.Request, id Id)
	// RemindLater Send today's daily reminder again at the user's later time. The reminder's "Remind me at" action calls this; asking twice for the same day queues it once.
	// (POST /push/remind-later)
	RemindLater(w http.ResponseWriter, r *http.Request)
	// UnsubscribePush Stop reminders on a device. Unknown endpoints are ignored.
	// (DELETE /push/subscriptions)
	UnsubscribePush(w http.ResponseWriter, r *http.Request)
	// SubscribePush Register this device for the daily reminder. Re-registering an endpoint updates its keys.
	// (POST /push/subscriptions)
	SubscribePush(w http.ResponseWriter, r *http.Request)
	// SendTestPush Send a test notification to every device the user has subscribed.
	// (POST /push/test)
	SendTestPush(w http.ResponseWriter, r *http.Request)

	// (GET /push/vapid-key)
	GetVapidKey(w http.ResponseWriter, r *http.Request)
	// UpdateSettings Replace the user's settings.
	// (PUT /settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request)
	// GetSetup Whether this instance still needs its first account, and whether it can be created now.
	// (GET /setup)
	GetSetup(w http.ResponseWriter, r *http.Request)
	// CompleteSetup Create the first account; sets the session cookie.
	// (POST /setup)
	CompleteSetup(w http.ResponseWriter, r *http.Request)
	// ListSpecies Saved species, matching q in the scientific or common name when given. Never calls a provider.
	// (GET /species)
	ListSpecies(w http.ResponseWriter, r *http.Request, params ListSpeciesParams)
	// CreateSpecies Save a species by hand (source manual).
	// (POST /species)
	CreateSpecies(w http.ResponseWriter, r *http.Request)
	// ImportSpecies Fetch a candidate's care details from its provider and save it (or refresh the saved copy).
	// (POST /species/import)
	ImportSpecies(w http.ResponseWriter, r *http.Request)
	// LookupSpecies Search the configured online providers. Costs provider API calls; results are cached.
	// (GET /species/lookup)
	LookupSpecies(w http.ResponseWriter, r *http.Request, params LookupSpeciesParams)

	// (GET /species/{id})
	GetSpecies(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateSpecies Edit a species' names and care defaults. Marks it user_edited.
	// (PUT /species/{id})
	UpdateSpecies(w http.ResponseWriter, r *http.Request, id Id)
	// GetStorage How much space grower uses, and when the last nightly backup ran.
	// (GET /storage)
	GetStorage(w http.ResponseWriter, r *http.Request)
	// DeleteTask Delete a task and its history.
	// (DELETE /tasks/{id})
	DeleteTask(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateTask Replace a task's schedule. History is kept.
	// (PUT /tasks/{id})
	UpdateTask(w http.ResponseWriter, r *http.Request, id Id)
	// LogTaskEvent Record that a task was done, skipped or snoozed.
	// (POST /tasks/{id}/events)
	LogTaskEvent(w http.ResponseWriter, r *http.Request, id Id)
	// GetToday Care due today or overdue, plus the next 7 days, for active plants.
	// (GET /today)
	GetToday(w http.ResponseWriter, r *http.Request)
}

