// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Login Log in with username and password; sets the session cookie.
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout End the current session and clear the cookie.
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// ChangePassword Change the password. Signs out every other session; this one stays signed in.
	// (POST /auth/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// UndoEvent Undo an event. It is kept but ignored from now on.
	// (DELETE /events/{id})
	UndoEvent(ctx context.Context, request UndoEventRequestObject) (UndoEventResponseObject, error)
	// ExportData Download everything as a zip (format in docs/export-format.md).
	// (GET /export)
	ExportData(ctx context.Context, request ExportDataRequestObject) (ExportDataResponseObject, error)
	// IdentifyPlant Suggest species for a plant photo with Pl@ntNet (optional; needs GROWER_PLANTNET_API_KEY).
	// (POST /identify)
	IdentifyPlant(ctx context.Context, request IdentifyPlantRequestObject) (IdentifyPlantResponseObject, error)
	// ListLocations All locations, ordered by name, with how many active plants each holds.
	// (GET /locations)
	ListLocations(ctx context.Context, request ListLocationsRequestObject) (ListLocationsResponseObject, error)

	// (POST /locations)
	CreateLocation(ctx context.Context, request CreateLocationRequestObject) (CreateLocationResponseObject, error)
	// DeleteLocation Delete a location. Its plants keep existing with no location.
	// (DELETE /locations/{id})
	DeleteLocation(ctx context.Context, request DeleteLocationRequestObject) (DeleteLocationResponseObject, error)
	// UpdateLocation Replace a location's fields.
	// (PUT /locations/{id})
	UpdateLocation(ctx context.Context, request UpdateLocationRequestObject) (UpdateLocationResponseObject, error)
	// GetMe The signed-in user, their settings and the server version.
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)

	// (DELETE /measurements/{id})
	DeleteMeasurement(ctx context.Context, request DeleteMeasurementRequestObject) (DeleteMeasurementResponseObject, error)

	// (PUT /measurements/{id})
	UpdateMeasurement(ctx context.Context, request UpdateMeasurementRequestObject) (UpdateMeasurementResponseObject, error)
	// DeletePhoto Delete a photo and its files. If it was the cover, the newest remaining photo becomes the cover.
	// (DELETE /photos/{id})
	DeletePhoto(ctx context.Context, request DeletePhotoRequestObject) (DeletePhotoResponseObject, error)
	// UpdatePhoto Replace a photo's caption and date.
	// (PUT /photos/{id})
	UpdatePhoto(ctx context.Context, request UpdatePhotoRequestObject) (UpdatePhotoResponseObject, error)
	// ListPlants Plants ordered by name. Archived plants are excluded unless archived=true.
	// (GET /plants)
	ListPlants(ctx context.Context, request ListPlantsRequestObject) (ListPlantsResponseObject, error)

	// (POST /plants)
	CreatePlant(ctx context.Context, request CreatePlantRequestObject) (CreatePlantResponseObject, error)
	// DeletePlant Permanently delete a plant. Archiving is the reversible option.
	// (DELETE /plants/{id})
	DeletePlant(ctx context.Context, request DeletePlantRequestObject) (DeletePlantResponseObject, error)

	// (GET /plants/{id})
	GetPlant(ctx context.Context, request GetPlantRequestObject) (GetPlantResponseObject, error)
	// UpdatePlant Replace a plant's fields, including whether it is archived.
	// (PUT /plants/{id})
	UpdatePlant(ctx context.Context, request UpdatePlantRequestObject) (UpdatePlantResponseObject, error)
	// ApplySpeciesCare Apply the linked species' care defaults to the plant's watering task.
	// (POST /plants/{id}/apply-species)
	ApplySpeciesCare(ctx context.Context, request ApplySpeciesCareRequestObject) (ApplySpeciesCareResponseObject, error)
	// SetPlantCover Choose the plant's cover photo, or clear it with null.
	// (PUT /plants/{id}/cover)
	SetPlantCover(ctx context.Context, request SetPlantCoverRequestObject) (SetPlantCoverResponseObject, error)
	// ListPlantEvents A plant's care history, newest first. Undone events are left out.
	// (GET /plants/{id}/events)
	ListPlantEvents(ctx context.Context, request ListPlantEventsRequestObject) (ListPlantEventsResponseObject, error)
	// ListMeasurements A plant's measurements, newest measured_on first.
	// (GET /plants/{id}/measurements)
	ListMeasurements(ctx context.Context, request ListMeasurementsRequestObject) (ListMeasurementsResponseObject, error)

	// (POST /plants/{id}/measurements)
	CreateMeasurement(ctx context.Context, request CreateMeasurementRequestObject) (CreateMeasurementResponseObject, error)
	// ListPlantPhotos A plant's photos, newest taken_at first.
	// (GET /plants/{id}/photos)
	ListPlantPhotos(ctx context.Context, request ListPlantPhotosRequestObject) (ListPlantPhotosResponseObject, error)
	// UploadPhoto Upload a JPEG or PNG (max 15 MB). The plant's first photo becomes its cover.
	// (POST /plants/{id}/photos)
	UploadPhoto(ctx context.Context, request UploadPhotoRequestObject) (UploadPhotoResponseObject, error)
	// ListPlantTasks A plant's care tasks, ordered by next due date.
	// (GET /plants/{id}/tasks)
	ListPlantTasks(ctx context.Context, request ListPlantTasksRequestObject) (ListPlantTasksResponseObject, error)

	// (POST /plants/{id}/tasks)
	CreateTask(ctx context.Context, request CreateTaskRequestObject) (CreateTaskResponseObject, error)
	// RemindLater Send today's daily reminder again at the user's later time. The reminder's "Remind me at" action calls this; asking twice for the same day queues it once.
	// (POST /push/remind-later)
	RemindLater(ctx context.Context, request RemindLaterRequestObject) (RemindLaterResponseObject, error)
	// UnsubscribePush Stop reminders on a device. Unknown endpoints are ignored.
	// (DELETE /push/subscriptions)
	UnsubscribePush(ctx context.Context, request UnsubscribePushRequestObject) (UnsubscribePushResponseObject, error)
	// SubscribePush Register this device for the daily reminder. Re-registering an endpoint updates its keys.
	// (POST /push/subscriptions)
	SubscribePush(ctx context.Context, request SubscribePushRequestObject) (SubscribePushResponseObject, error)
	// SendTestPush Send a test notification to every device the user has subscribed.
	// (POST /push/test)
	SendTestPush(ctx context.Context, request SendTestPushRequestObject) (SendTestPushResponseObject, error)

	// (GET /push/vapid-key)
	GetVapidKey(ctx context.Context, request GetVapidKeyRequestObject) (GetVapidKeyResponseObject, error)
	// UpdateSettings Replace the user's settings.
	// (PUT /settings)
	UpdateSettings(ctx context.Context, request UpdateSettingsRequestObject) (UpdateSettingsResponseObject, error)
	// GetSetup Whether this instance still needs its first account, and whether it can be created now.
	// (GET /setup)
	GetSetup(ctx context.Context, request GetSetupRequestObject) (GetSetupResponseObject, error)
	// CompleteSetup Create the first account; sets the session cookie.
	// (POST /setup)
	CompleteSetup(ctx context.Context, request CompleteSetupRequestObject) (CompleteSetupResponseObject, error)
	// ListSpecies Saved species, matching q in the scientific or common name when given. Never calls a provider.
	// (GET /species)
	ListSpecies(ctx context.Context, request ListSpeciesRequestObject) (ListSpeciesResponseObject, error)
	// CreateSpecies Save a species by hand (source manual).
	// (POST /species)
	CreateSpecies(ctx context.Context, request CreateSpeciesRequestObject) (CreateSpeciesResponseObject, error)
	// ImportSpecies Fetch a candidate's care details from its provider and save it (or refresh the saved copy).
	// (POST /species/import)
	ImportSpecies(ctx context.Context, request ImportSpeciesRequestObject) (ImportSpeciesResponseObject, error)
	// LookupSpecies Search the configured online providers. Costs provider API calls; results are cached.
	// (GET /species/lookup)
	LookupSpecies(ctx context.Context, request LookupSpeciesRequestObject) (LookupSpeciesResponseObject, error)

	// (GET /species/{id})
	GetSpecies(ctx context.Context, request GetSpeciesRequestObject) (GetSpeciesResponseObject, error)
	// UpdateSpecies Edit a species' names and care defaults. Marks it user_edited.
	// (PUT /species/{id})
	UpdateSpecies(ctx context.Context, request UpdateSpeciesRequestObject) (UpdateSpeciesResponseObject, error)
	// GetStorage How much space grower uses, and when the last nightly backup ran.
	// (GET /storage)
	GetStorage(ctx context.Context, request GetStorageRequestObject) (GetStorageResponseObject, error)
	// DeleteTask Delete a task and its history.
	// (DELETE /tasks/{id})
	DeleteTask(ctx context.Context, request DeleteTaskRequestObject) (DeleteTaskResponseObject, error)
	// UpdateTask Replace a task's schedule. History is kept.
	// (PUT /tasks/{id})
	UpdateTask(ctx context.Context, request UpdateTaskRequestObject) (UpdateTaskResponseObject, error)
	// LogTaskEvent Record that a task was done, skipped or snoozed.
	// (POST /tasks/{id}/events)
	LogTaskEvent(ctx context.Context, request LogTaskEventRequestObject) (LogTaskEventResponseObject, error)
	// GetToday Care due today or overdue, plus the next 7 days, for active plants.
	// (GET /today)
	GetToday(ctx context.Context, request GetTodayRequestObject) (GetTodayResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Login operation middleware
func (sh *strictHandler) Login(w http.ResponseWriter, r *http.Request) {
	var request LoginRequestObject

	var body LoginJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Login(ctx, request.(LoginRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Login")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(LoginResponseObject); ok {
		if err := validResponse.VisitLoginResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

